#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Context Compression module for A2A Mesh.

When a room's message history exceeds a configurable token threshold,
this module automatically compresses older messages into a summary,
keeping every agent's context window fresh and manageable.

Features:
- Token counting (heuristic approximation, ~4 chars/token)
- Extractive summarization of old messages (frequency-based)
- Sliding window: keeps recent N messages intact, summarizes the rest
- Per-room compression state tracking
- CLI demo mode for standalone testing

Usage:
    python context_compression.py                    # Run demo
    python context_compression.py --threshold 200    # Custom threshold
"""

import argparse
import hashlib
import json
import math
import re
import sys
import time
from dataclasses import dataclass, field, asdict
from typing import Dict, List, Optional, Tuple, Any
from collections import Counter, defaultdict


# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

DEFAULT_TOKEN_THRESHOLD = 500
DEFAULT_KEEP_RECENT = 10          # messages kept verbatim after compression
DEFAULT_MIN_MESSAGES_TO_COMPRESS = 5   # don't compress if fewer than this
APPROX_CHARS_PER_TOKEN = 4


# ---------------------------------------------------------------------------
# Token estimation
# ---------------------------------------------------------------------------

def estimate_tokens(text: str) -> int:
    """Estimate token count using a simple heuristic (~4 chars/token)."""
    if not text:
        return 0
    # Slightly more accurate: split on whitespace + count punctuation
    words = text.split()
    char_count = len(text)
    word_estimate = len(words) * 1.3  # average word ~1.3 tokens
    char_estimate = char_count / APPROX_CHARS_PER_TOKEN
    return max(int(math.ceil((word_estimate + char_estimate) / 2)), 1)


def estimate_message_tokens(msg: Dict[str, Any]) -> int:
    """Estimate tokens for a single message dict."""
    parts = []
    for key in ("agent", "content", "text", "body", "summary"):
        val = msg.get(key)
        if isinstance(val, str):
            parts.append(val)
    # Also count the JSON overhead roughly
    raw = " ".join(parts) if parts else json.dumps(msg, ensure_ascii=False)
    return estimate_tokens(raw)


def estimate_history_tokens(messages: List[Dict[str, Any]]) -> int:
    """Sum token estimates across a list of messages."""
    return sum(estimate_message_tokens(m) for m in messages)


