def _tokenize_words(text: str) -> List[str]:
    """Lowercase word tokens, stripping punctuation."""
    return re.findall(r"[a-záéíóöőúüű]+(?:-[a-záéíóöőúüű]+)*", text.lower())


def _split_sentences(text: str) -> List[str]:
    """Split text into sentences (handles . ! ? and Hungarian conventions)."""
    # Split on sentence-ending punctuation followed by whitespace + capital
    sentences = re.split(r'(?<=[.!?])\s+(?=[A-ZÁÉÍÓÖŐÚÜŰ])', text.strip())
    return [s.strip() for s in sentences if s.strip()]


def extractive_summary(messages: List[Dict[str, Any]], max_sentences: int = 5) -> str:
    """
    Produce an extractive summary of a list of messages.

    Strategy:
    1. Concatenate all message content.
    2. Build word-frequency scores (excluding stopwords).
    3. Score each sentence by sum of constituent word frequencies.
    4. Pick top-N sentences, preserving original order.
    """
    # Gather text content
    texts: List[str] = []
    for msg in messages:
        content = msg.get("content") or msg.get("text") or msg.get("body") or ""
        agent = msg.get("agent") or msg.get("sender") or msg.get("name") or "unknown"
        if content:
            texts.append(f"[{agent}]: {content}")

    if not texts:
        return ""

    full_text = "\n".join(texts)
    sentences = _split_sentences(full_text)

    if len(sentences) <= max_sentences:
        # Not enough to summarize — return condensed version
        return full_text if len(sentences) <= 2 else " ".join(sentences[:max_sentences])

    # Word frequency
    word_freq: Counter = Counter()
    for sentence in sentences:
        for word in _tokenize_words(sentence):
            if word not in STOPWORDS and len(word) > 2:
                word_freq[word] += 1

    # Normalize frequencies
    max_freq = max(word_freq.values()) if word_freq else 1
    for w in word_freq:
        word_freq[w] /= max_freq

    # Score sentences
    scored: List[Tuple[int, float, str]] = []
    for idx, sentence in enumerate(sentences):
        words = _tokenize_words(sentence)
        if not words:
            scored.append((idx, 0.0, sentence))
            continue
        score = sum(word_freq.get(w, 0.0) for w in words) / len(words)
        # Slight bonus for earlier sentences (recency / topic introduction)
        position_bonus = 1.0 - (idx / len(sentences)) * 0.15
        scored.append((idx, score * position_bonus, sentence))

    # Select top sentences
    top = sorted(scored, key=lambda x: x[1], reverse=True)[:max_sentences]
    top_sorted = sorted(top, key=lambda x: x[0])  # restore original order

    return " ".join(s[2] for s in top_sorted)


# ---------------------------------------------------------------------------
# Room context manager
# ---------------------------------------------------------------------------

@dataclass
class CompressionRecord:
    """Metadata about a single compression event."""
    timestamp: float
    original_message_count: int
    original_token_count: int
    compressed_token_count: int
    summary: str
    compressed_message_ids: List[str] = field(default_factory=list)


@dataclass
class RoomContext:
    """Tracks a single room's message history and compression state."""
    room_id: str
    messages: List[Dict[str, Any]] = field(default_factory=list)
    summaries: List[CompressionRecord] = field(default_factory=list)
    token_threshold: int = DEFAULT_TOKEN_THRESHOLD
    keep_recent: int = DEFAULT_KEEP_RECENT
    min_messages_to_compress: int = DEFAULT_MIN_MESSAGES_TO_COMPRESS

    def add_message(self, msg: Dict[str, Any]) -> bool:
        """
        Add a message to the room. Returns True if compression was triggered.
        """
        if "id" not in msg:
            msg = {**msg, "id": self._generate_id(msg)}
        if "timestamp" not in msg:
            msg = {**msg, "timestamp": time.time()}
        self.messages.append(msg)
        return self._maybe_compress()

    def add_messages(self, msgs: List[Dict[str, Any]]) -> bool:
        """Add multiple messages; compress once at the end if needed."""
        for msg in msgs:
            if "id" not in msg:
                msg = {**msg, "id": self._generate_id(msg)}
            if "timestamp" not in msg:
                msg = {**msg, "timestamp": time.time()}
            self.messages.append(msg)
        return self._maybe_compress()

    def current_token_count(self) -> int:
        return estimate_history_tokens(self.messages)

    def get_context_for_agent(self, include_summary: bool = True) -> List[Dict[str, Any]]:
        """
        Return the context an agent should see:
        - Optional summary message(s) at the front
        - Followed by all current (post-compression) messages
        """
        ctx: List[Dict[str, Any]] = []
        if include_summary and self.summaries:
            for rec in self.summaries:
                ctx.append({
                    "id": f"summary_{rec.timestamp}",
                    "agent": "system",
                    "content": f"[CONTEXT SUMMARY] {rec.summary}",
                    "type": "context_summary",
                    "timestamp": rec.timestamp,
                    "original_messages": rec.original_message_count,
                    "original_tokens": rec.original_token_count,
                    "compressed_tokens": rec.compressed_token_count,
                })
        ctx.extend(self.messages)
        return ctx

    def _maybe_compress(self) -> bool:
        """Check if compression is needed and perform it."""
        token_count = self.current_token_count()
        if token_count <= self.token_threshold:
            return False
        if len(self.messages) < self.min_messages_to_compress:
            return False
        if len(self.messages) <= self.keep_recent:
            return False

        # Split into old (to compress) and recent (to keep)
        split_idx = len(self.messages) - self.keep_recent
        old_messages = self.messages[:split_idx]
        recent_messages = self.messages[split_idx:]

        old_tokens = estimate_history_tokens(old_messages)
        summary_text = extractive_summary(old_messages, max_sentences=6)
        compressed_tokens = estimate_tokens(summary_text)

        record = CompressionRecord(
            timestamp=time.time(),
            original_message_count=len(old_messages),
            original_token_count=old_tokens,
            compressed_token_count=compressed_tokens,
            summary=summary_text,
            compressed_message_ids=[m.get("id", "") for m in old_messages],
        )
        self.summaries.append(record)
        self.messages = recent_messages
        return True

    @staticmethod
    def _generate_id(msg: Dict[str, Any]) -> str:
        raw = json.dumps(msg, sort_keys=True, ensure_ascii=False, default=str)
        return hashlib.sha256(raw.encode()).hexdigest()[:16]

    def stats(self) -> Dict[str, Any]:
        total_original = sum(r.original_token_count for r in self.summaries)
        total_compressed = sum(r.compressed_token_count for r in self.summaries)
        return {
            "room_id": self.room_id,
            "current_messages": len(self.messages),
            "current_tokens": self.current_token_count(),
            "compression_events": len(self.summaries),
            "total_original_tokens_compressed": total_original,
            "total_compressed_tokens": total_compressed,
            "compression_ratio": (
                f"{total_compressed / total_original:.2%}" if total_original > 0 else "N/A"
            ),
            "token_threshold": self.token_threshold,
        }


# ---------------------------------------------------------------------------
# Manager for multiple rooms
# ---------------------------------------------------------------------------

class ContextCompressor:
    """
    Manages context compression across multiple A2A Mesh rooms.

    Usage:
        compressor = ContextCompressor(token_threshold=500)
        compressor.add_message("room_1", {"agent": "alice", "content": "Hello!"})
        context = compressor.get_context("room_1")
    """

    def __init__(
        self,
        token_threshold: int = DEFAULT_TOKEN_THRESHOLD,
        keep_recent: int = DEFAULT_KEEP_RECENT,
        min_messages_to_compress: int = DEFAULT_MIN_MESSAGES_TO_COMPRESS,
    ):
        self.token_threshold = token_threshold
        self.keep_recent = keep_recent
        self.min_messages_to_compress = min_messages_to_compress
        self._rooms: Dict[str, RoomContext] = {}

    def _get_or_create_room(self, room_id: str) -> RoomContext:
        if room_id not in self._rooms:
            self._rooms[room_id] = RoomContext(
                room_id=room_id,
                token_threshold=self.token_threshold,
                keep_recent=self.keep_recent,
                min_messages_to_compress=self.min_messages_to_compress,
            )
        return self._rooms[room_id]

    def add_message(self, room_id: str, msg: Dict[str, Any]) -> bool:
        room = self._get_or_create_room(room_id)
        return room.add_message(msg)

    def add_messages(self, room_id: str, msgs: List[Dict[str, Any]]) -> bool:
        room = self._get_or_create_room(room_id)
        return room.add_messages(msgs)

    def get_context(self, room_id: str, include_summary: bool = True) -> List[Dict[str, Any]]:
        room = self._get_or_create_room(room_id)
        return room.get_context_for_agent(include_summary=include_summary)

    def get_room(self, room_id: str) -> Optional[RoomContext]:
        return self._rooms.get(room_id)

    def all_stats(self) -> Dict[str, Dict[str, Any]]:
        return {rid: room.stats() for rid, room in self._rooms.items()}

    def export_state(self) -> str:
        """Export all room state as JSON (for persistence/debugging)."""
        state = {}
        for rid, room in self._rooms.items():
            state[rid] = {
                "messages": room.messages,
                "summaries": [asdict(s) for s in room.summaries],
                "stats": room.stats(),
            }
        return json.dumps(state, indent=2, ensure_ascii=False, default=str)


