def run_demo(threshold: int, keep_recent: int, verbose: bool):
    """Run a demonstration of the context compression system."""
    print("=" * 70)
    print("A2A Mesh — Context Compression Demo")
    print("=" * 70)
    print(f"Token threshold: {threshold}")
    print(f"Keep recent messages: {keep_recent}")
    print(f"Messages to load: {len(DEMO_MESSAGES)}")
    print()

    compressor = ContextCompressor(
        token_threshold=threshold,
        keep_recent=keep_recent,
        min_messages_to_compress=3,
    )

    room_id = "debate_context_compression"

    for i, msg in enumerate(DEMO_MESSAGES):
        triggered = compressor.add_message(room_id, msg)
        room = compressor.get_room(room_id)
        current_tokens = room.current_token_count() if room else 0
        status = "COMPRESSED!" if triggered else "ok"
        print(f"  [{i+1:2d}/{len(DEMO_MESSAGES)}] {msg['agent']:6s} | "
              f"tokens={current_tokens:4d} | {status}")
        if triggered:
            rec = room.summaries[-1]
            print(f"         ↳ Compressed {rec.original_message_count} msgs "
                  f"({rec.original_token_count}→{rec.compressed_token_count} tokens)")
            if verbose:
                print(f"         ↳ Summary: {rec.summary[:120]}...")
        print()

    print("=" * 70)
    print("FINAL STATE")
    print("=" * 70)
    room = compressor.get_room(room_id)
    if room:
        stats = room.stats()
        for k, v in stats.items():
            print(f"  {k}: {v}")
        print()

        print("-" * 70)
        print("CONTEXT FOR A NEWLY JOINING AGENT:")
        print("-" * 70)
        context = compressor.get_context(room_id)
        for msg in context:
            msg_type = msg.get("type", "message")
            agent = msg.get("agent", "?")
            content = msg.get("content", "")
            prefix = "📋 [SUMMARY]" if msg_type == "context_summary" else "💬 [MSG]    "
            print(f"  {prefix} {agent}: {content[:100]}{'...' if len(content) > 100 else ''}")
        print()

        if verbose:
            print("-" * 70)
            print("FULL EXPORT (JSON):")
            print("-" * 70)
            print(compressor.export_state()[:2000])
            print("  ... (truncated)")

    print()
    print("=" * 70)
    print("Demo complete. Context compression is working.")
    print("=" * 70)


def main():
    parser = argparse.ArgumentParser(
        description="A2A Mesh Context Compression — auto-summarize room history when tokens exceed threshold."
    )
    parser.add_argument(
        "--threshold", type=int, default=DEFAULT_TOKEN_THRESHOLD,
        help=f"Token threshold to trigger compression (default: {DEFAULT_TOKEN_THRESHOLD})"
    )
    parser.add_argument(
        "--keep-recent", type=int, default=DEFAULT_KEEP_RECENT,
        help=f"Number of recent messages to keep intact (default: {DEFAULT_KEEP_RECENT})"
    )
    parser.add_argument(
        "--verbose", "-v", action="store_true",
        help="Show summary text and full JSON export"
    )
    args = parser.parse_args()

    run_demo(
        threshold=args.threshold,
        keep_recent=args.keep_recent,
        verbose=args.verbose,
    )


if __name__ == "__main__":
    main()